function Player2DHeadChangeTab:__init( main_, playerAvatarItemType_ )
    ---@type string[]
    self.allItemIdList = nil
    ---@type table<string, table>
    self.ownedItemIdMap = nil

    ---@type Player2DHeadChangeDialog
    self.main = main_
    ---@type Constants.PlayerAvatarItemType
    self.displayType_ = playerAvatarItemType_ -- 如: Constants.PlayerAvatarItemType.Avatar

    self.selectedIndex_ = nil 
    self.selectedItemId_ = nil
end


function Player2DHeadChangeTab:__delete()
end


-- =============================================================


function Player2DHeadChangeTab:InitData()
    ---
    self.allItemIdList  = PlayerInfoUtils.GetItemIdsByKind(self.displayType_)
    self.ownedItemIdMap = PlayerInfoUtils.GetItemHasByKind(self.displayType_)

    self:FindShowIdx()
end


function Player2DHeadChangeTab:FindShowIdx()
    for index, itemId in ipairs(self.allItemIdList) do
        if checkInt(itemId) == self:GetShowItemId() then
            self.showItemIndex_ = index -- 当前正在展示的 徽章
            break
        end
    end
end


------------------------------------------------------------------------

function Player2DHeadChangeTab:GetPlayerData()
    return checkTable(KCookie.Get("PersonalInfoDisplayDt"))
end



function Player2DHeadChangeTab:GetItemIdListNum()
    return #self.allItemIdList
end



function Player2DHeadChangeTab:WhenSwitchToThisTap()
    local needIdx = isNotNull(self.selectedIndex_) and self.selectedIndex_ or self:GetShowIndex()
    self:SetSelectedIndex(math.max(1, needIdx), true)
    self:FindShowIdx() -- 每次进入本 tab, 都要主动重新查找 正确的 show idx
end



function Player2DHeadChangeTab:GetDisplayType()
    return checkInt(self.displayType_)
end


function Player2DHeadChangeTab:SetSelectedItemId(oldIndex, isReload)
    local oldItemId      = self:GetSelectedItemId()
    self.selectedItemId_ = self:GetItemIdByIndex(self:GetSelectedIndex())

    if not isReload then
        local cell = self.main.ListView:GetShownItemByItemIndex(oldIndex - 1)
        if cell then
            KTool.SetActive(cell.transform:Find("ImgSelect"), false)
        end

        local newCell = self.main.ListView:GetShownItemByItemIndex(self:GetSelectedIndex() - 1)
        if newCell then
            KTool.SetActive(newCell.transform:Find("ImgSelect"), true)
        end
    end

    -- updateNew
    if PlayerInfoUtils.CheckAvatarIsNew(self:GetSelectedItemId()) then
        PlayerInfoUtils.UpdateAvatarNewStateById(self:GetSelectedItemId(), false)
        local newCell = self.main.ListView:GetShownItemByItemIndex(self:GetSelectedIndex() - 1)
        if newCell then
            KTool.SetActive(newCell.transform:Find("ImgNew"), false)
        end
    end

    self.main:UpdateLeftView(self.displayType_)
end

---@return number @ int
function Player2DHeadChangeTab:GetSelectedItemId()
    return checkInt(self.selectedItemId_)
end


function Player2DHeadChangeTab:SetSelectedIndex(index, isReload)
    local oldIndex      = self:GetSelectedIndex()
    self.selectedIndex_ = checkInt(index)
    self:SetSelectedItemId(oldIndex, isReload)
    
    self:UpdateTitleNew()
end


function Player2DHeadChangeTab:GetSelectedIndex()
    return checkInt(self.selectedIndex_)
end



function Player2DHeadChangeTab:SetShowItemId(oldIndex_)
    local index = self:GetShowIndex()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

    -- !! 此处需优化
    if self.displayType_ == Constants.PlayerAvatarItemType.Avatar then
        playerComponent.playerDojo.playerAvatar = self:GetItemIdByIndex(index)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.AvatarFrame then
        playerComponent.playerDojo.playerAvatarFrame = self:GetItemIdByIndex(index)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.Gender then
        playerComponent.playerDojo.gender = PlayerInfoUtils.GenderId2Type( self:GetItemIdByIndex(index) )
    else 
        printError("displayType_ 值异常: " .. tostring(self.displayType_))
    end

    local cell = self.main.ListView:GetShownItemByItemIndex(oldIndex_ - 1)
    if cell then
        --printError( "清除 old show idx = " .. tostring(oldIndex_) )
        KTool.SetActive(cell.transform:Find("ImgCurrent"), false)
    end

    local newCell = self.main.ListView:GetShownItemByItemIndex(index - 1)
    if newCell then
        --printError( "设置 new show idx = " .. tostring(index) )
        KTool.SetActive(newCell.transform:Find("ImgCurrent"), true)
    end

    self.main:UpdateLeftView(self.displayType_)
end

---@return number @ int
function Player2DHeadChangeTab:GetShowItemId()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

    -- !! 此处需缓存
    if self.displayType_ == Constants.PlayerAvatarItemType.Avatar then
        return checkInt(playerComponent.playerDojo.playerAvatar)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.AvatarFrame then
        return checkInt(playerComponent.playerDojo.playerAvatarFrame)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.Gender then
        return checkInt(PlayerInfoUtils.GetGenderId(playerComponent.playerDojo.gender))
    else 
        printError("displayType_ 值异常: " .. tostring(self.displayType_))
    end    
end

-- 当前正在展示的那个徽章
function Player2DHeadChangeTab:SetShowIndex(index_)
    local oldIndex = self:GetShowIndex()
    self.showItemIndex_ = index_
    self:SetShowItemId(oldIndex)
end


function Player2DHeadChangeTab:GetShowIndex()
    return checkInt(self.showItemIndex_)
end


function Player2DHeadChangeTab:GetItemIdByIndex(index_)
    return checkInt(self.allItemIdList[checkInt(index_)])
end

function Player2DHeadChangeTab:GetItemConfByItemId(itemId)
    return PlayerInfoUtils.GetHeadAvatarVo(itemId)
end


function Player2DHeadChangeTab:CheckItemIdIsOwned(itemId)
    -- 性别的 两个 item 默认送给玩家:
    if self.displayType_ == Constants.PlayerAvatarItemType.Gender then 
        return true
    end 
    return (checkTable(self.ownedItemIdMap)[tostring(itemId)] ~= nil)
end


function Player2DHeadChangeTab:ClearItemIdIsOwned(itemId)
    checkTable(self.ownedItemIdMap)[tostring(itemId)] = nil
    PlayerInfoUtils.SortItemIdsByKind(self.allItemIdList, self.displayType_)
end


---@return string 
function Player2DHeadChangeTab:GetLastSelectedOrSavedId()

    ---@type string
    local savedId = nil
    if self.displayType_ == Constants.PlayerAvatarItemType.Avatar then
        savedId = self:GetPlayerData().playerAvatar
    elseif self.displayType_ == Constants.PlayerAvatarItemType.AvatarFrame then 
        savedId = self:GetPlayerData().playerAvatarFrame
    elseif self.displayType_ == Constants.PlayerAvatarItemType.Gender then 
        savedId = tostring( PlayerInfoUtils.GetGenderId(self:GetPlayerData().gender) )
    else 
        printError("异常")
    end
    --local savedId = (self.displayType_ == Constants.PlayerAvatarItemType.Avatar) and self:GetPlayerData().playerAvatar or self:GetPlayerData().playerAvatarFrame
    local id = isNotNull(self.selectedItemId_) and self.selectedItemId_ or savedId
    return id
end


function Player2DHeadChangeTab:SetLastSelectedOrSavedId(headId)
    if self.displayType_ == Constants.PlayerAvatarItemType.Avatar then
        self:GetPlayerData().playerAvatar = checkInt(headId)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.AvatarFrame then 
        self:GetPlayerData().playerAvatarFrame = checkInt(headId)
    elseif self.displayType_ == Constants.PlayerAvatarItemType.Gender then 
        printError("undo... Gender")
    else 
        printError("undo...")
        --self:GetPlayerData().gender = 
    end
end


