-- 如果有了 新头像, 新头像框, 选择栏上会出现红色的 "New"
function Player2DHeadChangeTab:UpdateTitleNew()

    ---@type CommonTabToggleUp
    local env = CfUtils.GetLuaScr(self.main.CommonTabToggleUp, Constants.UILuaTablePath.ComUpToggle)
    for index, dt in ipairs(self.main.toggleData or {}) do
        if dt.type == checkInt(self.displayType_) then
            local node = env:GetTabNodeByIndex(index)
            if node then
                local newImg = node.transform:Find("ImgNew")
                local isNew = PlayerInfoUtils.CheckAvatarsHasNew(self.displayType_)
                --print("isNew = " .. tostring(isNew) )
                KTool.SetActive(newImg, isNew)
            end
        end
    end
end


return Player2DHeadChangeTab
